% aa_run_user_config_XXXX_design_TEST.m -- PLL setup and run
% Generated by GitHub Copilot under Lance Lascari's direction.
% Parameter layout/comments retained from the human-created aa_RunPllDesign_XXXX.m.
% GNU Octave first; MATLAB compatibility is a maintained goal.
% Edit the explicit assignments below as you would a copied example.
% The GUI is not needed to run or modify this saved script.
% Run by script name from its directory in the Octave GUI command window.
% Startup clears the command window, closes figures and clears the workspace.
% aa_RunPLLDesign_XXXX.m -- individual settings and
% invocation of the PLL analysis  %% 
%20251021LL -- at this point I've eliminated the stand alone call of the 
%pll analysis; it always needs to be called with the inputs setup like this file does -- just too much clunky/messy overhead to handle both cases.
%
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%NOTE:  Please read:
% Requested output frequency and F_tcxo_Hz remain explicit system inputs in file mode.
% File input details: reference file replaces noise; VCO file replaces noise and Kvco.
% --->when the flag is not set, then the manually entered params will be used
%
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%Copyright 2025 Lance Lascari / RFdude.com LLC       %
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
clc; close all; clear;

% Desired final output carrier (Hz), after the ideal output multiplier/divider.
pll_inputs_s.fout_desired_Hz=445000000;
% Output ratio: 1 = bare VCO, 2 = multiply by 2, 0.5 = divide by 2; VCO target = fout_desired_Hz/mult.
pll_inputs_s.mult=1; %multiplier
% PFD comparison frequency (Hz), not the oscillator carrier; sets N and sampling delay.
pll_inputs_s.Fref_Hz=100000;
% Manual VCO tuning sensitivity (Hz/volt); ignored when VCO file input supplies kvco.
pll_inputs_s.Kvco_Hz_volt=20000000;
% Charge-pump current / phase-detector gain (A/cycle); 1e-3 represents 1 mA.
pll_inputs_s.Kphi_A_cycle=0.001;
% Requested loop bandwidth (Hz); synthesized target, not guaranteed achieved crossover.
pll_inputs_s.BW_desired_Hz=2000;
% Requested phase margin (degrees); synthesis compensates for the PFD delay.
pll_inputs_s.PM_desired_deg=55;
% Additional attenuation request (dB) for third-pole synthesis at the PFD frequency; keep modest and positive.
pll_inputs_s.ATTEN_dB=0.01;

%pll_inputs_s.F_tcxo_Hz=12.8e6;  %need this for file or params
% Reference noise source: 0 = manual noise below, 1 = FileTCXO pn_struct data.
pll_inputs_s.bUseTCXOFromFile=0; %% if 1, load file below instead of params
% Reference oscillator carrier (Hz), used for R and noise scaling EVEN with file input.
pll_inputs_s.F_tcxo_Hz=16000000; %need this for file or params
%pll_inputs_s.FileTCXO="TCXO_ref_a.mat"; %uses standard pn_struct format    
%pll_inputs_s.FileTCXO="../pn/datfiles_local/vcso_1G.mat"; %uses standard pn_struct format    
%pll_inputs_s.FileTCXO="../pn/datfiles_local/ref40M.mat"; %uses standard pn_struct format    
% Reference noise MAT filename; requires pn_struct. Relative path is from this run script.
pll_inputs_s.FileTCXO='../pn/datfiles_local/16M_VCTCXO_20250930a_pndata.mat'; %uses standard pn_struct format    
% Manual reference SSB phase noise (dBc/Hz) at Ftcxo_ref_offset_Hz; ignored in reference file mode.
pll_inputs_s.Ntcxo_ref_dBc=-135;
% Offset frequency (Hz) of the manual reference noise anchor; existing noise_basic model supplies its shape.
pll_inputs_s.Ftcxo_ref_offset_Hz=100;

% VCO source: 0 = manual noise/Kvco, 1 = file noise and pn_struct.kvco.
pll_inputs_s.bUseVCOFromFile=0; %% if 1, use file below, otherwise params
% VCO noise MAT filename; requires pn_struct including kvco (Hz/volt). File fc does not replace the target.
pll_inputs_s.FileVCO='../pn/datfiles_local/vcso_1G.mat'; %uses standard pn_struct format    
% Manual open-loop VCO SSB noise (dBc/Hz) at Fvco_ref_offset_Hz; ignored in VCO file mode.
pll_inputs_s.Nvco_ref_dBc=-115; %VCO open loop noise
% Offset frequency (Hz) of the manual VCO noise anchor; not the carrier or loop bandwidth.
pll_inputs_s.Fvco_ref_offset_Hz=10000;
% Phase-detector noise figure of merit (dBc/Hz); core adds 10*log10(PFD frequency) and divider scaling.
pll_inputs_s.Npd_ref_dBc=-201; %Phase detector figure of merit (typically degrades 10*log10(Fpfd_Hz))

% Results basename (.mat); choose a new name for a new experiment. Leading _ keeps outputs git-ignored.
pll_inputs_s.def_filename='_rfd_pll_Design_XXXX.mat'; %default results file saved (phase noise)

% Lowest phase-noise/loop-analysis OFFSET frequency (Hz); must be positive.
pll_inputs_s.fstart_main_Hz=10;
% Highest OFFSET frequency (Hz); noise-file endpoints are extended if measured data is narrower.
pll_inputs_s.fstop_main_Hz=200000000;
% Number of logarithmically spaced offset points (integer >=2); affects measured crossover resolution.
pll_inputs_s.fsweep_main_pts=401; %100000; %3201;



% 1 = replace ALL synthesized C1/C2/R2/C3/R3 with values below; do not also enable third-pole-only.
pll_inputs_s.filter_override=0;
% 1 = hold R3/C3 below while C1/C2/R2 are synthesized; useful for bandwidth design-target sweeps.
pll_inputs_s.filter_override_3rdpole_only=0;

% Shunt capacitor at the charge-pump node (F); used only with full override. 1e-9 = 1 nF.
pll_inputs_s.CC1=9.9999999999999998e-13;
% Capacitor in the shunt R2/C2 branch (F); used only with full override.
pll_inputs_s.CC2=9.9999999999999998e-13;
% Resistor in the shunt R2/C2 branch (ohm); used only with full override.
pll_inputs_s.RR2=1;
% Capacitor at the VCO tuning node (F); used with full OR third-pole-only override.
pll_inputs_s.CC3=9.9999999999999998e-13;
% Series resistor from charge-pump node to VCO tuning node (ohm); used with either override mode.
pll_inputs_s.RR3=1;

% Master per-point figure-export switch; PDF/JPG settings below only apply when this is 1.
pll_inputs_s.bSaveFigs=1; %% this one needs to be enabled before the next two are evaluated
% Export original analysis figures as PDF when bSaveFigs=1; independent of viewer launch.
pll_inputs_s.bSaveFigsPDF=0;
% Export original analysis figures as JPG when bSaveFigs=1; each sweep point gets its own filenames.
pll_inputs_s.bSaveFigsJPG=1;
% 1 = small-signal frequency-step estimate; linear model, no saturation or cycle slips.
pll_inputs_s.bDoTransient=1; %% optional small-signal frequency-step response
% Starting frequency offset (Hz); both models share it. Large steps need nonlinear interpretation.
pll_inputs_s.transient_delta_f_Hz=500000; %% initial VCO frequency is fout_desired_Hz + this offset
% Simulation duration (seconds) for both transient models; extend if a case has not settled.
pll_inputs_s.transient_tmax_s=0.014999999999999999;
% Small-signal time samples (integer >=2); increases settling-time resolution, not nonlinear step density.
pll_inputs_s.transient_points=12501;
% Settling band (+/- Hz) around target; estimates require all remaining samples inside this band.
pll_inputs_s.transient_ftol_Hz=1000; %% frequency settling tolerance
% 1 = independent PFD/charge-pump acquisition simulation, including cycle slips; can run without small-signal.
pll_inputs_s.bDoTransientNonlinear=1; %% optional nonlinear PFD/charge-pump step response (cycle slips); uses the transient_* settings above
% Nonlinear steps per PFD period (integer >=10); time step = 1/(Fref_Hz*this value).
pll_inputs_s.transient_nl_steps_per_ref=100; %% simulation steps per reference period (>=10)
% Absolute lower VCO tuning frequency (Hz), not output frequency after mult; -Inf disables the lower limit.
pll_inputs_s.transient_nl_fvco_min_Hz=-Inf; %% VCO tuning range limits (absolute VCO freq), -Inf/Inf = unlimited
% Absolute upper VCO tuning frequency (Hz); Inf disables the upper limit; limits must contain the VCO target.
pll_inputs_s.transient_nl_fvco_max_Hz=Inf;
% Phase-noise plot limits [lower upper] (dBc/Hz); does not clip saved data or change integration.
pll_inputs_s.pn_ylimits=[-200 0];
% 1 = per-point CSV with system settings, filter values and total phase-noise table.
pll_inputs_s.bWriteCSVtable=1;


%% run control -- edit here for a single pass or a design-target sweep
% Single pass uses the assignments above; sweep mode changes one design target.
% Each point is synthesized, then the component overrides above are applied.
% Example: fix R3/C3 with third-pole-only override and sweep BW_desired_Hz.
% This redesigns C1/C2/R2 at each bandwidth; it is NOT a tolerance sweep.
% A full override with a bandwidth/phase-margin target sweep is rejected.
% For a large sweep, consider disabling core plots AND figure exports above.
% The dataset includes curves and metrics for later cc_pll_data_viewer browsing.
% 0 = one pass using pll_inputs_s above; 1 = repeat for sweep_values with the same component overrides.
run_options_s.bRunSweep=1;
% Design target field: BW_desired_Hz, PM_desired_deg, Fref_Hz, Kphi_A_cycle or fout_desired_Hz.
run_options_s.sweep_parameter='BW_desired_Hz';
% Target values in that field's units; e.g. [1000 2000 4000] Hz for bandwidth, or 1000:1000:4000.
run_options_s.sweep_values=[500 1000 2000 5000 10000];
% Lower phase-noise integration OFFSET (Hz); lies within the saved frequency grid.
run_options_s.integration_lower_Hz=100;
% Upper integration OFFSET (Hz); same limits at every point so RMS phase/EVM/residual FM are comparable.
run_options_s.integration_upper_Hz=1000000;
% Offsets (Hz) to compare in summary plots; noise is interpolated in dBc/Hz versus log10(offset).
run_options_s.noise_offsets_Hz=[100 1000 10000 100000];
% 1 = original analysis windows per point; 0 = hidden/closed core windows. Does not disable figure exports.
run_options_s.bShowCorePlots=1;
% 1 = launch cc_pll_data_viewer after the run; 0 = save results only, for later independent viewing.
run_options_s.bEnableDataViewer=1;
% 1 = replace an existing dataset and matching case files (default); set to 0 to protect them. Older surplus case files remain.
run_options_s.bOverwriteResults=1;

%% locate the analysis tools and run the configured experiment
% Relative noise/results paths are resolved from THIS script directory.
% Keep the relative tool path valid if moving the script to another folder.
run_options_s.base_directory=fileparts(mfilename('fullpath'));
pll_tool_directory=fullfile(run_options_s.base_directory,'.');
addpath(pll_tool_directory);
% A fresh workspace is used per point; the core still performs the PLL analysis.
% Saved outputs: <results basename>_data.mat and <results basename>_cases/.
% Pending/failed cases retain status; existing results are overwritten by default.
PLL_DATA_s=rfdude_pll_run(pll_inputs_s,run_options_s);

%% basic single-pass results (same names as the human-created runner)
% The runner already calculated these using the existing PN helper methods.
% pn_struct contains output carrier frequency, offset grid and total SSB noise.
% int_noise is double-sided RMS phase error (rad); EVM_tot = 20*log10(int_noise).
% Residual FM is in Hz and retains the existing unverified-method warning.
% Sweep results instead live in PLL_DATA_s.cases, one entry per requested point.
if ~run_options_s.bRunSweep
    pn_struct=PLL_DATA_s.cases{1}.pn_struct;
    int_noise=PLL_DATA_s.cases{1}.integrated_noise_rad
    EVM_tot=PLL_DATA_s.cases{1}.EVM_dB
    residual_FM_Hz=PLL_DATA_s.cases{1}.residual_FM_Hz
end

% To reopen stored results later: cc_pll_data_viewer('path_to_saved_data.mat')
% Select individual points/overlays, or compare noise/transient surfaces and metrics.
% Disabled/not-settled transient results are not fabricated zero lock times.

